package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.utils;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.security.AuthManager;
public class AnalyticsActivity extends AppCompatActivity{@Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Land Analytics","High-level indicators generated from your local records.");DatabaseManager m=new DatabaseManager(this);String uid=new AuthManager(this).getUserId();Cursor c=m.getDatabase().rawQuery("SELECT COUNT(*),COALESCE(SUM(CAST(area AS REAL)),0) FROM parcels WHERE owner_name=(SELECT name FROM users WHERE id=?)",new String[]{uid});if(c.moveToFirst()){LinearLayout box=utils.column(this);utils.row(box,this,"Parcels",String.valueOf(c.getInt(0)));utils.row(box,this,"Total area",String.format(java.util.Locale.US,"%.2f Acres",c.getDouble(1)));utils.addCard(root,box,this);}c.close();utils.setScreenContentView(this, root);}}
